 updateHazards(dt){for(const h of this.hazards){h.phase=(h.phase||0)+dt*this.difficulty.hazard;if(h.type==='axe')h.angle+=dt*h.speed*this.difficulty.hazard;if(h.type==='cannon'){h.cool-=dt;if(h.cool<=0){h.cool=3.1/this.difficulty.hazard;const y=h.y;this.projectiles.push({type:'cannon',x:h.x,y,vx:420*(h.dir||1),vy:0,r:8,life:3});this.audio?.hazard('cannon');}}if(h.type==='fireball'){h.cool-=dt;if(h.cool<=0){h.cool=3.6/this.difficulty.hazard;const tx=160+this.rand()*640;this.projectiles.push({type:'fireball',x:h.x,y:h.y,vx:(tx-h.x)*.8,vy:240,r:10,life:2.5});}}}}
